                        # the pruning tip at 3,111,901, in window 5); 3h's prefetch reads belong to windows 5-7
GAIN = 1.20             # E1: capped, F's heavy-part rate median at least this times N's
READS_KB = 20           # E3: capped, N's heavy-part read kB per block median at least this
F_READS_FRAC = 0.50     # E6: capped, F's heavy-part read kB per block median at most this times N's
NOHARM = 0.95           # E7: no cap, F's heavy-part rate at least this times N's
