                        # first pages by design, ahead of the prune, so its heavy-part reads are reported, not barred)
DR_LINES = 10           # E5: every drop-on run logs at least this many "LMDB G016 3e/3f/3g" lines, cachestat on
P_LINES = 10            # E10: every F and N run logs at least this many "G016 3h:" lines
P_LOOK = 100            # E10: F's look-ahead (blocks); N's must be 0
KIND = {"F": "3f", "V": "3f", "W": "3e"}   # F is 3h, whose LMDB prints 3f's lines
